CREATE TABLE IF NOT EXISTS offline_guard(id BIGINT PRIMARY KEY CHECK(id=1), clock_highwater BIGINT NOT NULL);
INSERT INTO offline_guard(id,clock_highwater) VALUES(1,0) ON CONFLICT(id) DO NOTHING;
CREATE TABLE IF NOT EXISTS offline_server_devices(id TEXT PRIMARY KEY, team_id TEXT NOT NULL REFERENCES identity_organizations(id), identity_id TEXT NOT NULL REFERENCES identity_subjects(id), public_key TEXT NOT NULL, payload TEXT NOT NULL, revoked BIGINT NOT NULL CHECK(revoked IN(0,1)));
CREATE TABLE IF NOT EXISTS offline_server_grants(id TEXT PRIMARY KEY, team_id TEXT NOT NULL REFERENCES identity_organizations(id), project_id TEXT NOT NULL REFERENCES tenant_projects(id), order_id TEXT NOT NULL REFERENCES team_orders(id), identity_id TEXT NOT NULL REFERENCES identity_subjects(id), device_id TEXT NOT NULL REFERENCES offline_server_devices(id), creation_key TEXT NOT NULL, request_sha TEXT NOT NULL, ticket TEXT NOT NULL, revoked BIGINT NOT NULL CHECK(revoked IN(0,1)), UNIQUE(identity_id,creation_key));
CREATE TABLE IF NOT EXISTS offline_reconciliations(id TEXT PRIMARY KEY, grant_id TEXT NOT NULL REFERENCES offline_server_grants(id), local_run_id TEXT NOT NULL, ordinal BIGINT NOT NULL, report_sha TEXT NOT NULL, report TEXT NOT NULL, receipt TEXT NOT NULL, UNIQUE(grant_id,local_run_id), UNIQUE(grant_id,ordinal));
CREATE TABLE IF NOT EXISTS offline_local_device(id BIGINT PRIMARY KEY CHECK(id=1), payload TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS offline_local_issuers(origin TEXT PRIMARY KEY, public_key TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS offline_local_grants(id TEXT PRIMARY KEY, ticket TEXT NOT NULL, used_runs BIGINT NOT NULL CHECK(used_runs>=0), sealed_credential TEXT, allow_no_key BIGINT NOT NULL CHECK(allow_no_key IN(0,1)), revoked BIGINT NOT NULL CHECK(revoked IN(0,1)));
CREATE TABLE IF NOT EXISTS offline_local_runs(id TEXT PRIMARY KEY, grant_id TEXT NOT NULL REFERENCES offline_local_grants(id), creation_key TEXT NOT NULL, ordinal BIGINT NOT NULL, state TEXT NOT NULL, revision BIGINT NOT NULL, payload TEXT NOT NULL, messages TEXT NOT NULL, UNIQUE(grant_id,creation_key), UNIQUE(grant_id,ordinal));
